import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import './Header.css';

const Header = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [cartCount, setCartCount] = useState(0);

useEffect(() => {
    if (user) {
        loadCartCount();
    }
    
    // Слушаем события обновления корзины
    const handleCartUpdate = () => loadCartCount();
    window.addEventListener('cartUpdated', handleCartUpdate);
    
    return () => {
        window.removeEventListener('cartUpdated', handleCartUpdate);
    };
}, [user]);

const loadCartCount = async () => {
    try {
        const response = await api.get('/cart');
        setCartCount(response.data.itemsCount || response.data.items?.length || 0);
    } catch (error) {
        console.error('Ошибка загрузки корзины:', error);
    }
};


  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <header className="header">
      <div className="header-container">
        <Link to="/" className="logo">
          🎮 GAME PORTAL
        </Link>

        <nav className="nav">
          <Link to="/" className="nav-link">🏠 Главная</Link>
          <Link to="/store" className="nav-link">🛒 Магазин</Link>
          {user && <Link to="/library" className="nav-link">📚 Библиотека</Link>}
          {user && <Link to="/chat" className="nav-link">💬 Чат</Link>}
          {user && <Link to="/cart" className="cart-link">🛒 Корзина {cartCount > 0 && <span className="cart-count">{cartCount}</span>}</Link>}
        </nav>

        <div className="header-actions">
          {user ? (
            <>
              <div className="user-info">
                <span className="user-balance">💰 {user.balance?.toFixed(2) || 0} ₽</span>
                <Link to="/profile" className="user-profile">
                  👤 {user.username}
                </Link>
              </div>
              <button onClick={handleLogout} className="logout-btn">
                Выйти
              </button>
            </>
          ) : (
            <Link to="/login" className="login-btn">🔐 Войти</Link>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;
